
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_hyb_gga_xc_cam_pbeh_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("hyb_gga_xc_cam_pbeh", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-3.751848679081029e-01, -3.740995718494926e-01, -3.725439087406797e-01, -3.703177197521429e-01, -3.671405552908079e-01, -3.626281285279965e-01, -3.562832155887025e-01, -3.475655900606265e-01, -3.361870035966013e-01, -3.230095687914608e-01, -3.096868846139253e-01, -3.011018220628980e-01, -2.911230518919848e-01, -2.692813871006475e-01, -2.320851658425085e-01, -1.752857625664490e-01, -1.043859950019048e-01, -3.954418081560217e-02, -8.648839807976821e-03, -9.729607458786180e-04]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


